// PROJETO SM3 — IDEMPOTENT CURATION QUEUE
// A project is re-curated only when:
// 1) it has never been AI-curated, OR
// 2) any analyzed media is not curated with the current curation version, OR
// 3) a media analysis is newer than the project's last CURATED_AT.
//
// This prevents repeated API spending and curation drift on unchanged projects.

const mediaRows = $('READ — ANALYZED MEDIA').all().map(i => i.json);
const projectRows = $input.all().map(i => i.json);

function n(v) {
  const x = Number(v);
  return Number.isFinite(x) ? x : 0;
}

function ts(v) {
  const x = Date.parse(String(v || ''));
  return Number.isFinite(x) ? x : 0;
}

const projectState = new Map(
  projectRows
    .filter(r => String(r.ID_PROJETO || '').trim())
    .map(r => [String(r.ID_PROJETO).trim(), r])
);

const eligibleMedia = mediaRows.filter(r =>
  String(r.ANALYSIS_STATUS || '').trim().toUpperCase() === 'ANALYZED' &&
  String(r.STORAGE_STATUS || '').trim().toUpperCase() === 'ONLINE' &&
  String(r.ID_PROJETO || '').trim()
);

const grouped = {};

for (const r of eligibleMedia) {
  const pid = String(r.ID_PROJETO).trim();
  if (!grouped[pid]) grouped[pid] = [];

  const editorial = n(r.EDITORIAL_SCORE);
  const technical = n(r.TECHNICAL_SCORE);
  const composition = n(r.COMPOSITION_SCORE);
  const visibility = n(r.TATTOO_VISIBILITY);

  const weighted =
    editorial * 0.45 +
    technical * 0.20 +
    composition * 0.20 +
    visibility * 0.15;

  const triage = String(r.TRIAGEM || '').toUpperCase();
  const triageAdjust =
    triage === 'SELECIONADO' ? 5 :
    triage === 'DESCARTAR' ? -30 : 0;

  const type = String(r.TIPO || '').toUpperCase();
  const kind = type.includes('VÍDEO') || type.includes('VIDEO')
    ? 'video'
    : 'image';

  grouped[pid].push({
    media_id: r.ID_MIDIA,
    kind,
    analysis_path: kind === 'video'
      ? `/data/media/contact_sheets/${pid}/${r.ID_MIDIA}.jpg`
      : `/data/media/proxies/${pid}/${r.ID_MIDIA}.jpg`,
    stage: r.ANALYSIS_STAGE || '',
    shot_type: r.SHOT_TYPE || '',
    editorial_score: editorial,
    technical_score: technical,
    composition_score: composition,
    tattoo_visibility: visibility,
    analysis_confidence: n(r.ANALYSIS_CONFIDENCE),
    recommended_use: r.USAR_EM || '',
    best_moment: r.MELHOR_TRECHO || '',
    visual_summary: r['CONTEÚDO_VISUAL'] || '',
    redundancy_hint: r.REDUNDANCY_HINT || '',
    precuation_score: Math.round(weighted + triageAdjust),

    _analyzed_at: r.ANALYZED_AT || '',
    _curation_status: r.CURATION_STATUS || '',
    _curation_version: r.CURATION_VERSION || ''
  });
}

const out = [];

for (const [pid, allMedia] of Object.entries(grouped)) {
  const state = projectState.get(pid) || {};

  const projectAlreadyCurated =
    String(state.CURATION_STATUS || '').toUpperCase() === 'AI_CURATED';

  const currentVersion = 'SM3_CURATION_V1';

  const mediaNeedsCuration = allMedia.some(m =>
    String(m._curation_status || '').toUpperCase() !== 'AI_CURATED' ||
    String(m._curation_version || '') !== currentVersion
  );

  const latestAnalysisMs = Math.max(0, ...allMedia.map(m => ts(m._analyzed_at)));
  const projectCuratedMs = ts(state.CURATED_AT);

  const staleByTime =
    latestAnalysisMs > 0 &&
    (projectCuratedMs === 0 || latestAnalysisMs > projectCuratedMs);

  const needsCuration =
    !projectAlreadyCurated ||
    mediaNeedsCuration ||
    staleByTime;

  if (!needsCuration) continue;

  allMedia.sort((a, b) =>
    b.precuation_score - a.precuation_score ||
    b.analysis_confidence - a.analysis_confidence ||
    String(a.media_id).localeCompare(String(b.media_id))
  );

  const shortlist = allMedia.slice(0, Math.min(12, allMedia.length)).map(m => {
    const {
      _analyzed_at,
      _curation_status,
      _curation_version,
      ...clean
    } = m;
    return clean;
  });

  out.push({
    json: {
      no_work: false,
      project_id: pid,
      candidate_count: shortlist.length,
      candidates: shortlist,
      context:
        'Curadoria editorial de projeto de tatuagem. Evitar quase-duplicatas. Preservar progressão narrativa e variedade visual.',
      recuration_reason: {
        project_already_curated: projectAlreadyCurated,
        media_needs_curation: mediaNeedsCuration,
        stale_by_time: staleByTime,
        latest_analysis_at: latestAnalysisMs ? new Date(latestAnalysisMs).toISOString() : '',
        previous_curated_at: state.CURATED_AT || ''
      }
    }
  });
}

if (out.length === 0) {
  return [{
    json: {
      no_work: true,
      status: 'CURATION_UP_TO_DATE',
      message: 'Nenhum projeto precisa de nova curadoria.',
      checked_at: new Date().toISOString()
    }
  }];
}

return out;

// PROJETO SM3 — BUILD REAL CURATION WRITES
// Machine curation only. This does NOT mean human approval.
// DISCARD is editorial status only; nothing is deleted.

const items = $input.all().map(i => i.json);
const now = new Date().toISOString();

return items.map(x => {
  const c = x.curation || {};
  const allowed = new Set(x.candidate_ids || []);

  const hero = String(c.hero_id || '');
  const selected = Array.isArray(c.selected_ids) ? c.selected_ids : [];
  const reserve = Array.isArray(c.reserve_ids) ? c.reserve_ids : [];
  const discard = Array.isArray(c.discard_ids) ? c.discard_ids : [];
  const carousel = Array.isArray(c.carousel_order) ? c.carousel_order : [];
  const reel = Array.isArray(c.reel_candidate_ids) ? c.reel_candidate_ids : [];
  const groups = Array.isArray(c.redundancy_groups) ? c.redundancy_groups : [];

  if (!hero || !allowed.has(hero)) {
    throw new Error(`CURATION_WRITE_BLOCK: invalid hero for ${x.project_id}`);
  }

  const covered = new Set([...selected, ...reserve, ...discard]);
  if (covered.size !== allowed.size || [...allowed].some(id => !covered.has(id))) {
    throw new Error(`CURATION_WRITE_BLOCK: buckets do not cover all candidates for ${x.project_id}`);
  }

  const overlaps =
    selected.filter(id => reserve.includes(id) || discard.includes(id)).length +
    reserve.filter(id => discard.includes(id)).length;

  if (overlaps > 0) {
    throw new Error(`CURATION_WRITE_BLOCK: overlapping curation buckets for ${x.project_id}`);
  }

  if (!selected.includes(hero)) {
    throw new Error(`CURATION_WRITE_BLOCK: hero is not selected for ${x.project_id}`);
  }

  const rankOrder = [
    hero,
    ...selected.filter(id => id !== hero),
    ...reserve,
    ...discard
  ];

  const redundancyById = new Map();

  groups.forEach((g, idx) => {
    const groupId = `RG${String(idx + 1).padStart(2, '0')}`;
    const members = Array.isArray(g.member_ids) ? g.member_ids : [];
    const preferred = String(g.preferred_id || '');
    const reason = String(g.reason || '').trim();

    if (preferred && !members.includes(preferred)) {
      throw new Error(`CURATION_WRITE_BLOCK: preferred redundancy ID not in group ${groupId}`);
    }

    for (const id of members) {
      if (!allowed.has(id)) {
        throw new Error(`CURATION_WRITE_BLOCK: unknown redundancy ID ${id}`);
      }
      if (redundancyById.has(id)) {
        throw new Error(`CURATION_WRITE_BLOCK: ${id} appears in more than one redundancy group`);
      }
      redundancyById.set(id, {
        group: groupId,
        preferred: id === preferred ? 'TRUE' : 'FALSE',
        reason
      });
    }
  });

  const mediaWrites = [...allowed].map(id => {
    const role =
      id === hero ? 'HERO' :
      selected.includes(id) ? 'SELECTED' :
      reserve.includes(id) ? 'RESERVE' :
      'DISCARD';

    const redundancy = redundancyById.get(id) || {
      group: '',
      preferred: '',
      reason: ''
    };

    const carouselPos = carousel.indexOf(id);
    const rankPos = rankOrder.indexOf(id);

    return {
      ID_MIDIA: id,
      CURATION_STATUS: 'AI_CURATED',
      CURATION_VERSION: 'SM3_CURATION_V1',
      CURATION_ROLE: role,
      CURATION_RANK: rankPos >= 0 ? rankPos + 1 : '',
      REDUNDANCY_GROUP: redundancy.group,
      REDUNDANCY_PREFERRED: redundancy.preferred,
      REDUNDANCY_REASON: redundancy.reason,
      CAROUSEL_POSITION: carouselPos >= 0 ? carouselPos + 1 : '',
      REEL_CANDIDATE: reel.includes(id) ? 'TRUE' : 'FALSE',
      CURATED_AT: now,
      CURATION_PROVIDER: x.provider || '',
      CURATION_MODEL: x.model || '',
      CURATION_CONFIDENCE: Number(c.confidence ?? ''),
      CURATION_RUN_ID: x.response_id || ''
    };
  });

  const projectWrite = {
    ID_PROJETO: x.project_id,
    CURATION_STATUS: 'AI_CURATED',
    CURATION_VERSION: 'SM3_CURATION_V1',
    CURATION_HERO_ID: hero,
    CURATION_SELECTED_IDS: selected.join(', '),
    CURATION_RESERVE_IDS: reserve.join(', '),
    CURATION_DISCARD_IDS: discard.join(', '),
    CURATION_CAROUSEL_ORDER: carousel.join(', '),
    CURATION_REEL_IDS: reel.join(', '),
    CURATION_NARRATIVE: String(c.narrative || '').trim(),
    CURATION_CONFIDENCE: Number(c.confidence ?? ''),
    CURATED_AT: now,
    CURATION_PROVIDER: x.provider || '',
    CURATION_MODEL: x.model || '',
    CURATION_RUN_ID: x.response_id || ''
  };

  return {
    json: {
      project_id: x.project_id,
      project_write: projectWrite,
      media_writes: mediaWrites,
      write_summary: {
        hero_id: hero,
        selected: selected.length,
        reserve: reserve.length,
        discard: discard.length,
        media_rows: mediaWrites.length,
        redundancy_groups: groups.length,
        carousel_items: carousel.length,
        reel_candidates: reel.length
      }
    }
  };
});

const out = [];
for (const item of $input.all()) {
  for (const row of (item.json.media_writes || [])) {
    out.push({json: row});
  }
}
return out;
